/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy import ndimage
x=np.load('source_pixels.npz')['rgb'].astype(int)
for name in ['yellow','purple']:
 vals=[]
 for im in x:
  R,G,B=im.transpose(2,0,1)
  if name=='purple': m=(B>80)&(R>55)&(B>G*1.12)&(R>G*1.05)&((R+B)>190)
  else:m=(R>120)&(G>90)&(B<G*.75)&(B<R*.65)
  lab,n=ndimage.label(m); cs=[]
  for j in range(1,n+1):
   yy,xx=np.where(lab==j)
   if len(xx)>=20 and yy.mean()<90:cs.append((len(xx),xx.mean(),yy.mean()))
  # purple max, yellow leftmost plausible circle
  if name=='purple': c=max(cs)
  else:c=min(cs,key=lambda z:z[1])
  vals.append((c[1],c[2]))
 print(name)
 for i,(a,b) in enumerate(vals):print(f'{i:02d} {a:6.2f} {b:5.2f}')
PY"
